import json,random,re
from pathlib import Path
D=json.load(open('source-material/slides.json'))
TITLES=['Foundations of development','Prenatal life & the newborn','Motor development','Physical growth & maturation','Speech, language & hearing','Emotional development','Cognitive development','Social & adaptive development']
SUB=['How biology, experience and relationships work together','The transition from conception to life outside the womb','Movement, coordination and everyday independence','Growth patterns, measurement and puberty','From early interaction to conversation and literacy','Feelings, attachment and self-regulation','Learning, memory, reasoning and play','Relationships, participation and daily living']
COLORS=['#407864','#6389a0','#bb7850','#8c719d','#4c8e91','#b66978','#7c8253','#697bb2']
lessons=[]
for raw in D:
 n=raw['number'];lessons.append(dict(id=n,title=TITLES[n-1],subtitle=SUB[n-1],color=COLORS[n-1],source=raw['source'],slides=raw['slides'],topics=[],milestones=[],questions=[],clarifications=[]))
def topics(n,data):
 for line in data.strip().splitlines():
  parts=line.split('~')
  if len(parts)==3:
   ss,title,body=parts; body,example=body.rsplit('|',1)
  else: ss,title,body,example=parts
  core,*bullets=body.split('|'); points='|'.join(bullets)
  lessons[n-1]['topics'].append(dict(id=f'L{n}T{len(lessons[n-1]["topics"])+1}',title=title,core=core,points=points.split('|'),example=example,slides=ss))
def timeline(n,data):
 for line in data.strip().splitlines():
  age,domain,text=line.split('~');lessons[n-1]['milestones'].append(dict(age=age,domain=domain,text=text))
def quiz(n,data):
 for line in data.strip().splitlines():
  stem,ans,w1,w2,w3,why=line.split('~');ix=len(lessons[n-1]['questions']);opts=[ans,w1,w2,w3];random.Random(n*1000+ix).shuffle(opts)
  lessons[n-1]['questions'].append(dict(id=f'CD{n}Q{ix+1:03}',lecture=n,question=stem,options=opts,answer=opts.index(ans),explanation=why,difficulty='Applied' if any(x in stem.lower() for x in ['child','baby','parent','student','caregiver','example','which response']) else 'Core'))
topics(1,'''
3–6~Growth and development~Growth describes measurable physical change; development includes changing abilities across physical, cognitive, emotional and social life. Both should be studied over time.|Height and weight are growth measures.|Functional skills reveal development.|Human development includes change and stability from conception through later life.~A child may gain height while also learning to take turns; these are related but different observations.
7~A lifespan perspective~Baltes’s framework treats development as lifelong, contextual and modifiable rather than a simple climb toward adulthood.|Gains and losses can coexist.|Biological and cultural influences change with age.|Resources are allocated differently across life.|Historical context shapes opportunities.~An adolescent may gain independent reasoning while adjusting to new social demands.
8–14,31–36~Domains and developmental periods~Motor, communication, cognition, emotion and social/adaptive skills interact. Age periods organize study but do not create identical schedules for every child.|Prenatal life precedes birth.|Infancy and toddlerhood lead into preschool and school years.|Adolescence combines biological and social transitions.|Young, middle and later adulthood remain developmental periods.~Putting on a shoe involves movement, understanding, motivation and adaptive independence.
15–20~Brain development and experience~Connections are formed, strengthened and reorganized through development and experience. Brain development does not stop at birth or at one preschool birthday.|Responsive interaction supports learning.|Nutrition and health support growth.|Safety and manageable stress support participation.|Synaptic pruning is selective reorganization, not a claim that connection numbers never change.~Repeated back-and-forth play gives a child opportunities to practise attention and interaction.
14,21–23~Biology and temperament~Genes, prenatal exposures, illness, maturation and temperament contribute to development. None should be treated as the sole destiny of the child.|Teratogens can disrupt prenatal development.|Maturation supports readiness for new abilities.|Temperament describes characteristic responses.|Caregiving can adapt to individual differences.~A cautious toddler may need more gradual introduction to an unfamiliar activity.
24–26~Attachment and contingent interaction~Attachment concerns an enduring emotional relationship; contingency means responding in a way connected to the child’s signals.|Comfort can support exploration.|Gestures can begin shared attention.|Reciprocity involves responding to one another.|Secure relationships are built through repeated interactions.~An adult follows a baby’s gaze, names the toy and pauses for a response.
27–30~Ecological and transactional models~Development takes place in interacting family, school, community and cultural environments. Transactional accounts emphasize influence in both directions between children and caregivers.|Immediate settings matter.|Connections between settings matter.|Wider resources and policies affect families.|Child behavior can change adult responses and vice versa.~A school routine changes family evenings, while family stress can influence classroom participation.
9–11,16–18,30~Risk, resilience and the first 1,000 days~The period from conception to the second birthday is a major opportunity for support, not the only opportunity to learn. Risks can accumulate, and protective relationships and resources matter.|Poverty can restrict opportunities without determining outcomes.|Malnutrition, illness and unsafe environments can compound risk.|Responsive care and stimulation are protective.|Historical prevalence estimates need their original year and denominator.~A family support programme combines nutrition, caregiver wellbeing and opportunities for play.
''')
topics(2,'''
3–7~Embryonic and fetal development~Early development transforms a fertilized cell into an embryo and then a fetus. Organ formation and later growth have different vulnerabilities.|Germ layers give rise to body structures.|The embryonic period is sensitive to disruption.|Later fetal life includes growth and maturation.|Pregnancy dating and post-fertilization dating differ by about two weeks.~An apparent timing disagreement may reflect different dating systems rather than a different biological event.
8–9~Developing nervous system~Neural structures emerge early, followed by extensive growth, connection formation and maturation. Having major structures at birth does not mean the brain is mature.|The neural tube contributes to the central nervous system.|Synapses continue changing after birth.|Myelination continues beyond early childhood in many pathways.|Hypoxia and harmful exposures can affect development.~A newborn’s brain already supports interaction while later abilities still require maturation and experience.
10–11~Fetal behavior and learning~Movements, swallowing and responses to stimulation emerge before birth. Repeated stimulation can lead to habituation.|Movement is not equivalent to adult voluntary control.|Sensory experience contributes to learning.|Habituation means reduced response to repeated familiar stimulation.|Breathing-like movements do not mean fetal lungs breathe air.~A reduced response across repeated presentations can indicate familiarization rather than simple lack of awareness.
13–16~Transition to parenthood and prenatal risk~Parents may experience excitement, uncertainty and increasing awareness of the fetus. These experiences vary across families rather than following compulsory emotional stages.|Fetal movement can affect parents’ sense of connection.|Mental health and practical support matter.|Infection, substances, illness and social adversity can raise risk.|A risk factor is not a diagnosis or inevitable outcome.~A worried parent may benefit from supportive discussion rather than being told that attachment must feel a certain way.
18–23~The newborn transition~The neonatal period covers approximately the first 28 days. Feeding, circulation, temperature regulation, arousal and social interaction adapt to life outside the womb.|Record weight, length and head circumference.|Observe tone, spontaneous movement and responsiveness.|Newborn vision is limited but useful.|Hearing and interaction are present while processing continues to mature.~A clinician considers the baby’s state and comfort when interpreting responsiveness.
24–27~States and caregiver interaction~Quiet sleep, active sleep, drowsiness, quiet alertness, active/fussy alertness and crying help organize observations of newborn behavior.|Arousal affects readiness to interact.|Caregivers can learn the infant’s signals.|Feeding and comfort needs affect state.|Quiet alert periods often support face-to-face engagement.~An adult waits until a baby is calmly alert rather than treating every sleepy response as an inability.
28–39~Reflexes: recognize the response~Primitive reflexes support early function and provide information in a trained clinical examination. Some fade with maturation, while protective responses appear later.|Rooting turns the face toward feeding-related stimulation.|Moro includes an arm opening-and-return pattern.|Palmar and plantar grasp involve grasping responses.|Plantar grasp is not the Babinski response.|ATNR, Galant and oculocephalic responses have distinct patterns.|The parachute response appears later and persists.~A student distinguishes curled toes in plantar grasp from an extending great toe in an infant plantar response; testing belongs to trained clinicians.
19–20~Supporting the early relationship~Prenatal circumstances, birth experiences and postnatal support influence interaction without determining attachment from one moment.|Support caregiver mental health.|Facilitate appropriate early contact and feeding support.|Rooming-in can create interaction opportunities.|A relationship can develop even when medical care delays initial contact.~A family whose baby needs neonatal care can build closeness through supported interactions over time.
''')
topics(3,'''
3–5~Principles of motor development~Gross motor skills involve posture and large movements; fine motor skills involve controlled hand and finger use. The two systems cooperate in daily tasks.|Cephalocaudal trends move from head control toward lower-body control.|General responses become more differentiated.|Rates vary across children.|Reflex integration supports voluntary movement.~Reaching for a cup needs stable posture and coordinated hand control.
6–16~Early gross motor sequence~The lecture follows changing head control, prone support, rolling and sitting into later standing and mobility. Ages are approximate teaching anchors.|Head lag reduces as control improves.|Forearm support progresses toward straighter-arm support.|Sitting changes from supported to more independent.|Crawling patterns vary and are not an obligatory identical pathway.~Observe the quality and symmetry of movement rather than assigning a diagnosis from one birthday.
17–23~Walking, stairs and preschool movement~Mobility becomes more independent and adaptable, then develops into running, stair negotiation, jumping, hopping and skipping.|Cruising differs from independent walking.|Support and step pattern matter on stairs.|Balance develops through practice and maturation.|Preschool coordination improves across several skills.~Walking while holding furniture is not the same milestone as walking independently.
24–25~Fine motor foundations~Reaching, grasping, purposeful release and wrist rotation support later manipulation. Vision and postural control contribute to these activities.|Skills cooperate rather than develop in isolation.|Opportunities and safe objects matter.|Small objects can create choking hazards.|Manipulation supports exploration and self-care.~Opening a container requires one hand to stabilize and the other to turn.
26–36~From hand regard to manipulation~Infants progress from early hand postures and looking to reaching, transferring, precision grasp and controlled release.|Visual tracking supports interaction.|A pincer grasp uses thumb and finger.|Early and refined grasps are different.|Scribbling and block play create practice opportunities.~Picking up a safe large snack with precision differs from grasping a toy with the whole hand.
37–46,58~Drawing, dressing and hand use~Preschool tasks combine visual-motor control, finger coordination and learned routines. Figure copying becomes more complex but should not be treated as a universal age test by itself.|Circle, square and triangle copying increase in complexity.|Pencil control develops beyond one fixed grip label.|Dressing involves sequencing as well as dexterity.|Do not force a preferred writing hand.~A child practises buttons with patient support and gradually needs less help.
49–54~Variation, delay, deviancy and dissociation~Delay concerns slower attainment; deviancy concerns an unusual pattern; dissociation concerns uneven development across domains. These descriptions guide further inquiry rather than name a diagnosis.|Consider opportunity, vision, tone and health.|Advanced movement does not prove higher intelligence.|Regression deserves prompt professional discussion.|Assess across settings and over time.~A child strong in running but struggling with fine tasks needs a domain-specific profile, not a single global label.
43,55–57~Assessment and the technoference assignment~The slides introduce Gesell’s maturational observations and the Peabody motor scales. Standardized tools require the correct edition, administration and interpretation.|Separate gross and fine motor findings.|Observation and caregiver reports complement tools.|Screening is not diagnosis.|The assignment examines technology interrupting adult–child interaction, not simply all screen use.~An adult silencing notifications during play can protect a back-and-forth interaction routine.
''')
topics(4,'''
4–7~Infant growth patterns~Weight, length and head circumference follow changing trajectories during infancy. The lecture’s doubling/tripling rules are rough teaching heuristics, not universal diagnostic thresholds.|Early weight loss needs context and follow-up.|Subsequent growth should be monitored serially.|Body proportions change.|Growth charts are more informative than one remembered number.~A clinician plots repeated measurements rather than deciding wellbeing from a single weight.
8–16~Toddler, preschool and school growth~Growth usually slows after infancy while proportions, strength and coordination change. Appetite can fluctuate, but feeding quality remains important.|Legs lengthen relative to the trunk.|Gait and alignment change with maturation.|School-age stamina and complex movement increase.|Persistent or asymmetric concerns need contextual assessment.~A toddler eating less than during rapid infant growth is considered alongside the overall trajectory.
17–24,45–47~Adolescence and sexual maturation~Puberty brings changes in secondary sexual characteristics and body composition. Sequence and timing vary; Tanner stages describe characteristics, not exact chronological age.|Breast budding and testicular enlargement are key early changes in their respective pathways.|Adrenal hair changes are not identical to gonadal puberty.|Growth acceleration and voice changes can occur.|Five-stage ratings assess different features separately.~A student separates pubic-hair staging from breast or genital staging rather than assigning one age from appearance.
25–33~Dental development~Teeth form, erupt and are later shed according to variable patterns. Primary and permanent dentitions have different schedules.|Primary teeth number 20.|Permanent first molars commonly emerge around six to seven years.|Premolars do not simply replace that first-molar milestone.|Delayed eruption or enamel changes have several possible explanations.|A tooth-eruption chart supports learning better than assuming every child follows one exact month.
34–35~Skeletal maturation~Bone maturation can provide information about progress toward physical maturity. Bone age and chronological age are different measures.|Assessment uses appropriate reference standards.|Interpretation considers growth and puberty.|An estimate does not guarantee exact adult height.|Imaging is a clinical decision, not a home developmental test.~Two children of the same age can differ in skeletal maturation.
36–44~Measurement and growth charts~Measure carefully, record accurately and interpret a series using an appropriate chart. Weight, recumbent length or standing height, and head circumference answer different questions.|Technique and equipment affect readings.|Percentiles describe a reference distribution.|A percentile alone is not a diagnosis.|Trajectory, family history and clinical context matter.~An unexpected plotted change should first prompt checking measurement and context.
48–53~Patterns that need assessment~Weight, linear growth, head growth and puberty can deviate for nutritional, familial, endocrine or other medical reasons. The slide lists are examples rather than one-to-one diagnoses.|Distinguish undernutrition and excess weight patterns.|Short stature can be familial or illness-related.|Large head size does not alone prove hydrocephalus.|Early or late puberty needs an individual assessment.~A pattern across height, weight and symptoms is more informative than guessing a syndrome from stature.
54–57,61~Growth as a proxy: use and limits~Physical growth can flag health and social risk but is not a complete measure of cognition, language or social development. Historical risk estimates should retain their original date and definition.|Association is not equivalence.|Development requires direct domain-specific observation.|Monitoring can be integrated with primary care.|The assignment asks for a referenced 1,500–2,000-word analysis of the proxy claim.~A child’s expected height does not establish that language comprehension is developing as expected.
''')
topics(5,'''
3–5~Communication has several channels~Communication exchanges information through language and other signals. Speech is one way of expressing language, not its entire definition.|Gestures, posture and eye contact can communicate.|Signed and written languages are linguistic systems.|Tone and rhythm contribute paralinguistic information.|Avoid equating all communication with spoken words.~A child points, looks toward a caregiver and vocalizes to request a toy.
9–11,19–21~Speech, comprehension and expression~Speech involves producing spoken sounds; language concerns structured meaning. Receptive language concerns understanding, while expressive language concerns producing messages.|Motor coordination supports spoken output.|Comprehension can exceed spoken vocabulary.|Production can be spoken, signed or written.|The slide’s production paragraph mistakenly repeats understanding of written language.~A child can understand give me the cup before saying a comparable sentence.
12–18~Hearing and listening~Hearing provides auditory access; listening involves attention, selection, memory and interpretation. Auditory processing continues to develop after birth.|Localization concerns identifying sound direction.|Acoustic and contextual evidence contribute.|Early recognition does not equal adult-level processing.|A hearing concern warrants appropriate assessment rather than assumptions.~A child may detect a sound yet struggle to follow a complex spoken instruction.
6–8,22–29~Prelinguistic foundations~Turn-taking, joint attention, gestures, cooing and babbling create foundations for later language. They are meaningful developmental achievements before first words.|Joint attention involves shared focus.|Babbling includes speech-like sound play.|Gestures can request and share interest.|Adult responses support reciprocal routines.~An adult follows the infant’s pointing and comments on the same object.
30–35~First words and toddler communication~Meaningful words emerge alongside gestures and growing comprehension. Vocabulary and combinations develop with considerable individual and language variation.|Receptive and expressive vocabulary are not identical.|First words need communicative meaning, not perfect adult pronunciation.|Early combinations build new messages.|The course’s numerical vocabulary estimates are not standalone diagnostic cutoffs.~More milk communicates a combination of meanings beyond naming milk alone.
36–40~Preschool language~Children increasingly ask questions, use grammatical patterns, tell events and follow more complex messages. Intelligibility depends on listener, language, context and measurement.|Pronouns, tense and plurals develop progressively.|Stories become richer.|Do not equate sentence word count with age.|MLU is an average calculated from a language sample, with the counting unit specified.~Compare several utterances when examining grammatical complexity rather than counting one sentence.
43–47~School language and literacy~Oral language supports reading, spelling, writing and academic participation. Later development includes more organized narratives, abstract vocabulary and figurative meanings.|Written language is produced as well as understood.|Oral-language difficulty can affect literacy.|Support must reflect language and learning context.|School-age abilities continue developing beyond basic conversation.~A learner can speak conversationally yet need help explaining a science concept in writing.
48–52~A language-supportive environment~Responsive conversation, shared reading and opportunities to express ideas help learning. Interaction matters more than merely exposing a child to background speech.|Follow the child’s interests.|Pause for a response.|Expand rather than shame an attempt.|Use familiar languages and meaningful routines.|During picture-book reading, ask an accessible question and build on the child’s answer.
''')
topics(6,'''
3–7~Emotions and emotional development~Emotional development includes recognizing, expressing and managing feelings, understanding others and building relationships. Feelings, physiological responses and behavior are connected but not identical.|Pleasure, distress, interest and fear are examples of early emotion categories.|Self-conscious emotions involve additional self-awareness.|Expression is one clue, not an infallible mind-reading tool.|Empathy develops through interaction and learning.~An adult notices a child’s posture and situation rather than labeling one facial movement with certainty.
8–12,25–26~Early emotional expression~Reflexive smiling and socially responsive smiling differ. Emotional patterns become more differentiated and context-sensitive across development.|Early smiles can occur without a social partner.|Social smiling emerges in early interaction.|Do not impose one exact month when all fear begins.|Individual differences and caregiver responses matter.~A caregiver responds to a baby’s emerging social smile with a brief face-to-face exchange.
13–20~Attachment phases~Bowlby’s teaching model moves from early signaling to selective preference, clear attachment and more reciprocal relationships. The phases are approximate, not compulsory deadlines.|Early signals attract care.|Familiar people gain importance.|A secure base supports exploration.|Language and perspective-taking later support negotiation about separation.~A toddler checks back with a familiar caregiver while exploring a new room.
14–21,33~Relationships and responsive care~Attachment is enduring and person-specific; it is not proof of one perfect birth moment or a child’s temperament score. Relationships remain capable of change.|Contact-seeking can communicate distress.|Consistency and sensitivity matter.|Multiple trusted caregivers can contribute.|Historical deprivation studies do not justify claims that later support is useless.~A child in a new caregiving arrangement can build trust through repeated responsive care.
22–24~Temperament and goodness of fit~Temperament describes characteristic patterns of reactivity and regulation. It interacts with experience rather than fixing a permanent personality fate.|Observe intensity and adaptability.|Adjust routines to the individual.|Do not label a cautious child as disobedient.|Caregiver interpretation affects the interaction.~A slower-to-warm child receives time to observe before joining a group.
27–34~Wariness, separation and social referencing~Infants may show stranger wariness or separation distress as recognition and mobility develop. Social referencing uses another person’s emotional signals to interpret uncertainty.|Timing and intensity vary.|Distress is not automatically an attachment disorder.|A calm familiar adult can provide cues.|Social referencing is related to, but not identical with, theory of mind.~An infant checks a parent’s face before approaching an unfamiliar toy.
35–38~Autonomy and tantrums~Growing independence can exceed a toddler’s language and inhibitory control. Adults can co-regulate while maintaining clear, developmentally appropriate limits.|Words can gradually support self-regulation.|Fatigue and frustration affect behavior.|Avoid treating one duration or frequency as a diagnosis.|Persistent, severe or harmful patterns deserve professional discussion.~A caregiver names frustration and offers a safe choice while keeping a limit.
39–43~Preschool regulation and empathy~Children practise labeling emotions, tolerating limits and handling peer conflict. External guidance gradually supports more internal regulation.|Predictable routines help.|Overly harsh or inconsistent responses can hinder learning.|Imaginary play is not automatically pathology.|Empathic responses and repair can be modelled.~A teacher helps a child say I am upset instead of hitting.
44–48~Moral reasoning and adolescence~The lecture introduces Kohlberg’s preconventional, conventional and postconventional levels. These are a theory of reasoning, not fixed diagnostic ages or proof of moral worth.|Early reasoning may focus on consequences.|Social approval and order become relevant.|Principles and rights can organize later arguments.|Adolescents negotiate belonging, values and independence.~Two students may support the same action for different reasons, which matters in analysing moral reasoning.
''')
topics(7,'''
3–5~Cognition, working memory and expertise~Cognition includes perceiving, remembering, reasoning and understanding. Working memory and accumulated knowledge help explain changes in performance.|Prior experience supports new learning.|Familiarity can reduce task demands.|Development varies across contexts.|Performance is not explained by age alone.~A child solves a familiar puzzle more easily than an equally complex unfamiliar one.
6–13,46~Piaget’s four stages~The classical sequence is sensorimotor, preoperational, concrete operational and formal operational. It is a theoretical framework rather than a rigid universal timetable.|Sensorimotor learning links action and perception.|Preoperational thought uses symbols but can be perceptually centered.|Concrete operations support conservation and reversibility.|Formal operations involve abstract or hypothetical reasoning.~A conservation task examines whether changed appearance is confused with changed amount.
15–18~Early learning and habituation~Infants attend to visual, tactile, auditory and other information. Repetition and exploration reveal learning before spoken explanations are possible.|Habituation is reduced response to a repeated stimulus.|Novelty can renew attention.|Looking does not directly reveal every concept.|Repeated self-produced actions create experience.~An infant repeatedly moves a hand while watching its changing position.
19–21~Object exploration and permanence~Object permanence concerns understanding that an object continues to exist when out of sight. Searching and looking-time tasks provide different evidence.|Infants inspect, transfer and manipulate objects.|Occlusion tasks need careful interpretation.|Failure to search can reflect motor or memory demands.|No single task fixes the exact age of all object knowledge.~A hidden toy can be studied through search behavior or attention to an unexpected event.
23–25~Toddler problem solving~Mobility broadens exploration, and object use, anticipation, sorting and pretend routines become more complex.|In/out and part/whole relations develop.|Meaningful object use supports learning.|Imitation and make-believe differ from random manipulation.|Opportunities and familiarity affect performance.~A child uses a toy cup in a pretend tea routine and sorts blocks by one property.
26–30~Preschool thought and play~Symbolic play expands into scenarios and roles. Egocentrism means difficulty taking another viewpoint, not simply selfishness.|Animism attributes lifelike qualities to objects.|Magical thinking can confuse wishes with causes.|Play supports practice and expression.|Understanding may exceed what a difficult task reveals.~A child pretends a box is a bus and negotiates passenger roles.
31–38~School readiness and self-efficacy~School tasks increasingly demand attention, language processing and organized practice. Beliefs about competence and opportunities to succeed influence participation.|Reading, writing and number skills become central.|Task demands should be scaffolded.|External and internal motivations can coexist.|Repeated failure can reduce willingness to try without establishing fixed inability.~A teacher breaks a challenging task into achievable steps and gives specific feedback.
39–42~Adolescent reasoning~Abstract and hypothetical reasoning, metacognition and planning can develop unevenly. Emotion and familiarity influence whether a skill is used in a situation.|Reasoning about thinking is metacognition.|Consequences and alternatives can be compared.|No unsupported percentage is a universal attainment rate.|Individual variation is more useful than assuming one sex always develops earlier.~A student reasons logically about a science task but needs support in a stressful peer decision.
''')
topics(8,'''
4–11~Social and adaptive skills~Social development concerns participation with others; adaptive behavior concerns managing everyday demands and independence in context.|Self-care and social responsibility are related but distinct.|Expectations reflect age, culture and opportunity.|A difficulty is not a moral defect.|Support can improve access and participation.~A child learns both how to put on a coat and when to ask for help.
6,12~Faces and social referencing~Infants attend to faces and use partners’ expressions as information. A caregiver’s signal is interpreted within a situation rather than read as a perfect emotion label.|Shared attention supports learning.|Responsive partners create reciprocal routines.|Infants are active participants.|Perception and social interpretation develop together.~A child looks toward a familiar adult before approaching an unfamiliar object.
14–19~Early social interaction~The lecture traces face regard, social smiling, vocal exchange, imitation, gesture games and response to familiar people. Timing is approximate.|Mirror interest is not proof of full self-recognition.|Mouthing can be exploration.|Pointing can request or share interest.|Frustration can accompany restrictions.~A baby alternates vocalizing with a caregiver during a simple game.
20–22~Toddler self-care~Feeding, cup use, dressing participation and indicating needs develop through practice and support. Toileting readiness is individual, and nighttime dryness is not an automatic two-year expectation.|Offer safe opportunities.|Separate independence from perfect performance.|Model routines step by step.|Do not punish accidents as intentional misconduct.~A toddler helps with dressing before managing the whole sequence alone.
23–25~Preschool peers and play~Sharing, turn-taking, rules and household participation become more practiced. These abilities remain context-sensitive and need adult scaffolding.|Cooperative play develops gradually.|Storytelling can mix imagination and experience.|Rules may be interpreted from a child’s viewpoint.|Avoid expecting perfect sharing at one birthday.~An adult coaches two children to alternate turns rather than labeling one unsuccessful attempt as a fixed trait.
26~Everyday regulation~Sleep, eating and toileting involve physiological needs, routines, emotional security and learned skills.|Seek patterns rather than blame.|Consider comfort, access and communication.|Support families with realistic expectations.|Persistent concerns require appropriate discussion.~A predictable bedtime routine can support settling without implying that all sleep difficulties are behavioral.
28–30~Middle-childhood relationships and values~Teachers, peers, community experiences and media broaden the child’s social world. Belonging, prosocial behavior and moral reasoning become important.|Friendship patterns vary across cultures and individuals.|Possessions do not determine everyone’s popularity.|Children negotiate family and community expectations.|Safety and inclusion shape opportunities.~A class develops a fair way to include a new student in a game.
31–33~Adolescent identity and relationships~Privacy, peer affiliation, body awareness and future planning become prominent. Conflict or risk is not inevitable, and supportive family relationships remain relevant.|Media messages can affect self-presentation.|Autonomy and connection can coexist.|Later planning may become more realistic.|Do not assume one universal sequence of friendship or gender-group patterns.~A teenager negotiates privacy while agreeing on a communication plan with caregivers.
34–36~Adaptive assessment~The Vineland family of instruments evaluates adaptive functioning through domains such as communication, daily living and socialization, with motor content depending on edition and form.|Use the appropriate standardized version.|Reports reflect opportunities and setting.|Scores need qualified interpretation.|Screening, assessment and diagnosis are different activities.~A child’s daily-living profile can reveal support needs that are not captured by an academic test.
''')

# Course timelines: deliberately qualitative where the slides provide inconsistent cutoffs.
timeline(1,'''
Prenatal~Period~Conception to birth; biological development occurs within a maternal and social context.
Infancy & toddlerhood~Period~Birth through approximately two years; rapid change in movement, communication and interaction.
Early childhood~Period~Preschool years; growing language, play, regulation and everyday independence.
Middle childhood~Period~School years; more organized learning, peer participation and complex movement.
Adolescence~Period~Puberty, identity, abstract thought and increasing autonomy develop on overlapping trajectories.
''')
timeline(2,'''
Early prenatal life~Prenatal~Cell division, implantation, germ-layer formation and early neural development.
Embryonic period~Prenatal~Major organ formation; exact week labels require a stated dating convention.
Fetal period~Prenatal~Growth, sensory experience and ongoing organ maturation; 24 weeks does not mean mature lungs.
Birth–28 days~Newborn~Physiological adaptation, state regulation, feeding and early reciprocal contact.
Quiet alertness~State~Eyes open with relatively low activity; useful opportunities for interaction.
Active sleep / quiet sleep~State~Different behavioral and physiological patterns; do not confuse all movement with wakefulness.
''')
timeline(3,'''
Early infancy~Gross motor~Progressive head control, prone support and reduction of head lag.
Later infancy~Gross motor~Rolling, sitting and increasing mobility; order and timing are not identical for all children.
Around the first birthday~Gross motor~Pulling up and cruising may precede independent steps; use milestone windows rather than an exact deadline.
Toddler years~Gross motor~Independent walking becomes more adaptable; running, kicking and stairs develop with support and practice.
Preschool years~Gross motor~Balance, jumping, hopping, tricycle use and more complex coordination are practised.
Infancy~Fine motor~Reaching, grasping, transfer, precision grasp and deliberate release become more coordinated.
Toddler years~Fine motor~Scribbling, block construction, page turning and simple self-care provide practice.
Preschool years~Visual-motor~More complex copying, cutting and fastenings develop; task conditions and experience matter.
''')
timeline(4,'''
Infancy~Growth~Rapid growth with changing velocity; interpret serial measures, not a single doubling rule.
Toddler & preschool years~Growth~Slower growth and changing body proportions can accompany variable appetite.
Middle childhood~Growth~Steady progression, changing dentition and increasing physical strength.
Pubertal transition~Maturation~Secondary sexual characteristics and growth acceleration; sequence and timing vary.
Tanner 1~Clinical stage~Prepubertal secondary sexual characteristics.
Tanner 2~Clinical stage~Early changes: breast budding or testicular/scrotal enlargement; pubic hair is assessed separately.
Tanner 3~Clinical stage~Further enlargement and development; different features may not share the same stage.
Tanner 4~Clinical stage~Advanced maturation; breast areola/papilla may form a secondary mound in the breast-rating system.
Tanner 5~Clinical stage~Mature secondary sexual characteristics; stage is not a precise age calculator.
''')
timeline(5,'''
Birth–3 months~Communication~Crying, early vocalization, attention to voices and reciprocal engagement.
4–6 months~Communication~Vocal play and early babbling expand alongside responsiveness and interaction.
7–12 months~Communication~Gesture, imitation, familiar-word understanding and speech-like babbling become more developed.
Second year~Communication~Meaningful words, growing comprehension and emerging combinations expand communication.
Preschool years~Communication~Questions, grammar, narrative and understanding of more complex instructions develop.
School years~Communication~Conversation links increasingly with literacy, organized explanation and figurative or abstract language.
Across ages~Listening~Detection, localization, attention, interpretation and language understanding are related but different skills.
''')
timeline(6,'''
Early infancy~Emotion~Distress, interest, soothing and emerging social smiling support exchanges.
Later infancy~Relationships~Selective preferences, stranger wariness and separation responses may become more apparent.
Toddler years~Emotion~Autonomy can outpace language and inhibition; adults support co-regulation.
Preschool years~Emotion~Emotion labeling, perspective-taking, empathy and limit negotiation develop through practice.
School years~Emotion~Self-evaluation, achievement and belonging influence feelings and motivation.
Adolescence~Emotion~Identity, peers, future concerns and increasingly complex regulation interact.
Preconventional~Moral theory~Kohlberg: reasoning organized around consequences and self-interest; not a fixed age diagnosis.
Conventional~Moral theory~Kohlberg: reasoning organized around relationships, approval and social order.
Postconventional~Moral theory~Kohlberg: reasoning may appeal to rights, social contracts and principles; not an inevitable endpoint.
''')
timeline(7,'''
Sensorimotor~Piaget~Approximately birth–2 years in the classical model: action, perception and developing object permanence.
Preoperational~Piaget~Approximately 2–7 years: symbols and pretend play with limits in some logical tasks.
Concrete operational~Piaget~Approximately 7–11 years: conservation and reversible operations with concrete information.
Formal operational~Piaget~Approximately 11 years onward in the classical account: hypothetical and abstract reasoning, with substantial task-dependent variation.
Infancy~Learning~Habituation, sensory exploration, imitation and object manipulation offer evidence of cognition.
Preschool years~Play~Make-believe expands into roles and scenarios; play supports problem-solving and social learning.
School years~Learning~Increasing attention and curriculum demands interact with language, motivation and opportunities.
Adolescence~Reasoning~Metacognition, alternatives and future planning develop unevenly across situations.
''')
timeline(8,'''
Early infancy~Social~Face regard, responsiveness and social smiling support interaction.
Later infancy~Social~Imitation, gestures, shared games and familiar-person preferences become more evident.
Toddler years~Adaptive~Participating in feeding and dressing, communicating needs and seeking help.
Preschool years~Social~Peer play, turn-taking, simple rules and increasing self-care with support.
School years~Social~Friendship, belonging, teachers, prosocial behavior and community expectations broaden participation.
Adolescence~Social~Privacy, identity, peers and future planning coexist with continuing relationships and support needs.
''')
quiz(1,'''
Which observation measures growth most directly?~An increase in height~Taking turns~Recognizing a familiar face~Using a new word~Growth refers to measurable physical change. For example, plotting height over time describes growth; taking turns describes social development.
A child learns to dress independently. Which interpretation is best?~Several developmental domains work together~Only physical growth is involved~Only emotional development is involved~Domains develop without influencing each other~Dressing combines coordination, understanding, sequencing and motivation. Developmental domains interact in everyday tasks.
What is central to a lifespan view of development?~Change continues throughout life~Development ends at puberty~All change is a gain~Context has no influence~Development includes gains, adjustments and losses across life. An adult learning a new skill is still developing.
Which example best illustrates a contingent response?~An adult names the object the baby points toward~An adult ignores every gesture~An adult repeats unrelated words continuously~An adult chooses all activities without observing the baby~A contingent response connects to the child's signal. Naming a pointed-at toy supports shared attention.
What does temperament describe?~Characteristic patterns of responding~A fixed measure of intelligence~A diagnosis of attachment disorder~The number of skills attained~Temperament concerns typical responses such as approach, activity and reactivity. A cautious child may benefit from a gradual introduction.
Which statement fits a transactional model?~Children and caregivers influence one another~Only caregivers influence children~Only genes influence development~A child's behavior never changes adult responses~Influence moves in both directions. A baby's signals shape adult responses, which then influence the baby's experience.
Which example illustrates an ecological influence?~School and family routines affecting participation~Height increasing without any contextual influence~A reflex occurring in isolation~One test score determining the child's future~Ecological models consider connected settings. Consistent support at home and school may improve participation.
What does resilience mean in development?~Positive adaptation in the presence of adversity~Never experiencing stress~Being unaffected by relationships~An inherited guarantee against difficulty~Resilience is adaptation despite challenges. A supportive adult can be a protective factor during family disruption.
How should brain development be understood?~Connections continue to be reorganized through experience~The brain is complete at birth~Every connection remains unchanged~Learning stops after early childhood~Experience and maturation shape connections over time. Repeated language interaction provides practice for developing systems.
What does the first 1,000 days emphasize?~The period from conception through roughly the second birthday~Only the first 1,000 days after school entry~A deadline after which learning is impossible~A period when caregiving has no influence~This period highlights early nutrition, health and responsive care. It is an important opportunity, not a claim that later support cannot help.
''')
quiz(2,'''
Why distinguish gestational age from age since fertilization?~They use different starting points~They always differ by six months~Only one measures time~They describe different infants~Gestational age is generally counted from the last menstrual period, about two weeks before fertilization. The dating convention changes the week label.
Why can exposure timing matter during pregnancy?~Different organs have sensitive periods of development~All organs form at the same instant~Every exposure has the same effect~Timing eliminates the importance of dose~Developing organs are vulnerable at different times. Timing, dose and other circumstances affect risk.
Which statement about fetal lungs is most accurate?~They continue maturing late in pregnancy~They are fully mature at 24 weeks in every fetus~They stop developing after the embryonic period~They function exactly like adult lungs before birth~Lungs mature progressively. Reaching a particular week does not mean a fetus has mature lungs or no risk from early birth.
Which newborn state is usually useful for face-to-face interaction?~Quiet alertness~Deep sleep~Continuous crying~Active sleep with closed eyes~A quietly alert baby is awake and relatively settled. This can provide a good opportunity for gentle interaction.
What does rooting primarily support?~Orienting toward feeding-related stimulation~Independent walking~Voluntary writing~Protective arm extension during a fall~Rooting turns the face toward stimulation near the mouth. It helps a newborn find a feeding source.
Which response describes palmar grasp?~Finger flexion around stimulation of the palm~Turning the head toward cheek stimulation~Extension of the great toe~An alternating stepping pattern~Palmar means the palm of the hand. A grasp response closes the fingers around an object contacting the palm.
Why should plantar grasp and the Babinski response be distinguished?~Toe grasping differs from great-toe extension~They are identical names for rooting~Both describe eye movements~Neither involves the foot~Plantar grasp involves toe flexion; the infant plantar response may include great-toe extension. Similar body location does not mean the same reflex.
Which statement best describes the parachute response?~A protective response that appears later and persists~A feeding reflex present only before birth~A reflex that must disappear in the first month~Another term for palmar grasp~Protective extension develops later than many primitive newborn responses and persists. It is assessed by trained clinicians.
What is the safest learning approach to neonatal reflexes?~Learn patterns and rely on trained clinical assessment~Practise dropping a baby to elicit Moro~Diagnose from one home observation~Assume all reflexes disappear at the same age~Reflex interpretation depends on the examination and age. Never create a fall or unsafe movement to test a response.
A baby needs neonatal care and early contact is delayed. What follows?~A close relationship can still develop through supported interaction~Attachment is permanently impossible~Caregiver responsiveness no longer matters~Only the first hour determines all later relationships~Relationships build through repeated care. Families can develop closeness even when medical circumstances delay initial contact.
''')
quiz(3,'''
Which task is primarily fine motor?~Manipulating a button~Running across a room~Standing independently~Jumping forward~Fine motor tasks use precise hand and finger control. Buttoning also requires vision and sequencing.
What does a cephalocaudal trend describe?~Control developing broadly from head toward lower body~Control developing only from feet upward~All muscles maturing simultaneously~Fine motor skill always preceding head control~Head control generally develops before later standing and walking. This describes a broad trend rather than an exact timetable.
How does cruising differ from independent walking?~Cruising uses furniture or another support~Cruising requires no support~Cruising is a drawing skill~Cruising means crawling on hands and knees~A child moving along furniture is cruising. Walking independently requires taking steps without that support.
Which observation best illustrates a pincer grasp?~Using thumb and finger to pick up an object~Holding a large ball against the chest~Grasping with the whole palm alone~Kicking a ball~A pincer grasp uses the thumb and a finger for precision. Use safe objects because small objects can be choking hazards.
A child skips crawling but develops other mobility skills. What is the best interpretation?~Consider the overall pattern and movement quality~Crawling absence alone proves a disorder~Walking is therefore impossible~The child must have advanced intelligence~Motor pathways vary. Assessment considers the full history, symmetry, function and progress rather than one isolated milestone.
What does developmental dissociation describe?~Uneven performance across domains~Loss of every acquired skill~Identical progress in all domains~Normal physical growth alone~A child may have strong gross motor skills and weaker language skills. That uneven profile is dissociation and needs interpretation in context.
What is developmental regression?~Loss of previously acquired skills~Learning a new skill slowly~Having a preferred toy~A temporary wish for help during one task~Loss of established abilities warrants prompt professional discussion. For example, losing words previously used consistently differs from simply learning new words slowly.
What is a suitable response to emerging hand preference?~Provide practice without forcing the opposite hand~Force every child to use the right hand~Treat left-handedness as a delay~Avoid all drawing activities~Hand preference varies. Support comfortable, effective hand use rather than forcing a particular side.
What is technoference in the lecture assignment?~Technology interrupting interpersonal interaction~Every use of technology for learning~A type of grasp reflex~A standardized motor score~Technoference concerns interruptions, such as checking notifications during a child's attempt to engage. The interaction context matters.
What distinguishes screening from diagnosis?~Screening identifies a need for closer assessment~Screening always establishes the final diagnosis~Screening replaces history and examination~Screening measures only height~A screening result flags possible concerns. A fuller assessment considers history, observations and appropriate tools before diagnostic conclusions.
''')
quiz(4,'''
Why are serial growth measurements useful?~They show the child's trajectory over time~They eliminate measurement error~They diagnose every developmental disorder~They replace nutrition history~A pattern across visits is more informative than one point. An unexpected change should be checked and interpreted with the clinical context.
How should an infant weight-doubling rule be used?~As an approximate teaching heuristic~As a universal diagnostic threshold~As proof that feeding is always adequate~As a substitute for growth charts~Doubling rules summarize typical patterns but do not fit every infant. Appropriate growth standards and the clinical picture are more useful.
A newborn has substantial weight loss. What is the best response?~Assess feeding, hydration and clinical circumstances~Assume any loss is harmless~Stop all feeding~Diagnose a lifelong growth disorder from one weight~Early weight loss needs context. A concerning amount or associated symptoms requires assessment rather than automatic reassurance.
What do Tanner stages describe?~Patterns of pubertal physical maturation~A child's reading grade~Levels of moral reasoning~Five newborn behavioral states~Tanner staging describes features such as breast or genital development and pubic hair. It is not an intelligence or school achievement scale.
Which teeth commonly appear around early school age?~First permanent molars~All permanent premolars before age three~All wisdom teeth~A new set of primary incisors~First permanent molars commonly erupt around six to seven years. Dental timing varies and should not be confused with premolar eruption.
What is bone age used to estimate?~Skeletal maturation~Vocabulary size~Attachment security~Auditory attention~Bone age assesses skeletal maturity, often using an appropriate radiograph. It is interpreted alongside growth and other clinical information.
Why can measurement technique matter?~Poor positioning can distort height or length~Technique never changes the result~Weight and height are interchangeable~One instrument fits every measurement~Accurate positioning and calibrated equipment support valid measurements. An apparent growth change can sometimes reflect measurement error.
Can physical growth alone represent all development?~No, functional and contextual information is also needed~Yes, height measures every domain~Yes, weight proves language competence~Yes, puberty stage determines social skills~Growth is one important dimension. Communication, learning, relationships and daily functioning require their own observations.
Which statement about brain maturation is appropriate?~It continues beyond the early school years~All myelination ends at age five~Brain development ends when teeth erupt~Height predicts all brain connections~Brain systems mature over an extended period. One early-childhood age cannot mark completion of every process.
What is a sound approach to a growth concern?~Verify measurements and assess the pattern and context~Diagnose solely from comparison with a sibling~Ignore a persistent downward change~Use a single unreferenced age rule~Check technique, plot appropriate measurements and consider health, feeding and family history. One comparison cannot supply the full explanation.
''')
quiz(5,'''
Which example is receptive language?~Understanding an instruction~Producing a speech sound~Writing a story~Naming an object aloud~Receptive language concerns understanding. Following “put the cup on the table” shows comprehension rather than spoken expression.
Which example is expressive language?~Using words or signs to communicate an idea~Detecting a quiet tone~Understanding a sentence silently~Turning toward a sound only~Expression conveys meaning through spoken, signed or written forms. A child signing “more” communicates expressively.
How does speech differ from language?~Speech is one means of producing a language message~Speech and language always mean identical things~Language consists only of articulation~Speech includes all reading comprehension~Speech concerns sound production and related processes; language is a system for meaning. A child can use language through signs without speech.
What does mean length of utterance summarize?~Average utterance length in specified linguistic units~The child's age in months~Hearing sensitivity in decibels~The number of conversations per day~MLU averages units such as morphemes or words across utterances. It is not simply another name for age.
Which caregiver action supports early communication?~Follow the child's interest and take conversational turns~Correct every sound immediately~Speak continuously without pausing~Avoid gestures until speech is perfect~Responsive turns connect words with attention and meaning. Naming a toy, pausing and responding creates a useful learning exchange.
Why does hearing assessment matter when language is delayed?~Access to sound can affect communication learning~All language delays prove hearing loss~Hearing is unrelated to speech~Only reading requires hearing assessment~Hearing differences are one possible influence on communication. Assessment helps distinguish contributing factors without assuming a single cause.
What is joint attention?~Sharing attention to an object or event with another person~Playing alone without noticing anyone~Repeating an isolated sound during sleep~Measuring the loudness of a voice~A child looks between an adult and an interesting toy or follows a point. Shared attention supports opportunities to connect meaning and communication.
Which is a prelinguistic communication behavior?~Using a gesture to request something~Writing a grammatical paragraph~Reading a chapter silently~Explaining an abstract metaphor~Gestures, gaze and early vocalizations communicate before fluent words. Reaching toward a caregiver can express a request.
How should vocabulary counts at a specific age be interpreted?~As context-dependent indicators alongside other information~As identical requirements for every language learner~As a diagnosis by themselves~As unrelated to opportunities for communication~Language exposure, measurement and individual variation matter. A useful assessment considers understanding, gestures, progress and everyday function as well as words.
How are language and literacy connected?~Spoken or signed language skills support later reading and writing~Literacy begins without any language foundation~Speech clarity alone guarantees reading mastery~Vocabulary becomes irrelevant at school~Vocabulary, narrative and sound or language awareness support literacy. Reading also requires specific instruction and practice.
''')
quiz(6,'''
What is co-regulation?~An adult helping a child manage arousal and feelings~A baby independently suppressing every emotion~An adult refusing all emotional support~A method of measuring height~Young children rely on another person's calm and support. Naming a feeling and helping a child settle provides a foundation for later self-regulation.
What does attachment primarily concern?~An enduring emotional relationship~A permanent personality score~A reflexive hand movement~A measure of school achievement~Attachment involves the child's relationship with a caregiver, including seeking comfort and using that relationship to support exploration.
Which response is sensitive to temperament?~Introduce a cautious child gradually to a new setting~Require all children to react identically~Treat shyness as proof of low intelligence~Punish an initial fear response~Temperament describes characteristic responses. Gradual introductions can help a cautious child participate without assigning a negative label.
A toddler looks at a caregiver before approaching an unfamiliar toy. What is this?~Social referencing~Skeletal maturation~Palmar grasp~Formal operational reasoning~Social referencing uses another person's emotional cues to guide behavior. A calm caregiver response may help the toddler approach.
What is a constructive response to a tantrum?~Provide safety, calm support and consistent limits~Assume one tantrum establishes a diagnosis~Demand a complex explanation during peak distress~Remove every limit permanently~A distressed child often needs help settling before reasoning. Afterward, simple language and consistent routines can support learning.
How should stranger wariness be interpreted?~In relation to age, temperament and context~As proof of an insecure relationship~As identical in every infant~As a deliberate moral failure~Wariness varies. A child may need time with an unfamiliar person, especially when tired or in a new setting.
Which behavior supports emerging autonomy?~Offer two acceptable choices~Remove every opportunity to choose~Expect adult-level emotional control~Avoid all predictable routines~Limited choices let a child practise agency within safe boundaries. Choosing between two shirts supports independence without removing structure.
What is a limitation of Kohlberg's stages?~They are a theory of moral reasoning rather than a fixed timetable for every person~They directly measure physical growth~They prove all adolescents reason identically~They describe newborn reflexes~The theory organizes types of justification for moral choices. Culture, context and the limits of the model matter when applying it.
Which example illustrates emotion labeling?~Saying “You feel disappointed because playtime ended”~Telling a child all feelings are wrong~Ignoring every attempt to communicate~Equating crying with bad character~Naming feelings connects experience with language. A caregiver can validate disappointment while keeping the bedtime limit.
Can one facial expression establish an infant's exact emotion?~No, behavior and context must be considered~Yes, expressions always have one meaning~Yes, crying always means anger~Yes, smiling rules out every difficulty~Expressions are clues rather than perfect readouts. Crying may accompany hunger, fatigue, discomfort or distress.
''')
quiz(7,'''
What is working memory?~Holding and using information briefly~Storing every experience permanently~A measure of height~A reflex present only at birth~Working memory supports tasks such as remembering two instructions while carrying them out. It differs from permanent long-term storage.
What is object permanence?~Understanding that an object continues to exist when hidden~Knowing the name of every object~Remembering only visible objects~Assuming hidden objects have vanished permanently~Searching for a hidden toy illustrates the developing idea that it still exists. Performance depends on task demands as well as understanding.
In Piaget's account, what is assimilation?~Interpreting an experience using an existing scheme~Changing a scheme to fit new information~Copying a word without meaning~Losing all previous knowledge~Calling a new four-legged animal “dog” can reflect use of an existing scheme. Accommodation would involve revising that scheme.
What is accommodation in Piaget's theory?~Modifying a scheme when experience does not fit~Using an unchanged scheme for everything~A type of skeletal measurement~The complete absence of learning~Learning that a cat differs from a dog may require adjusting categories. The child changes the existing mental organization.
Which example illustrates symbolic play?~Using a block as a pretend telephone~Dropping a toy only to hear a sound~Standing with support~Tracking a moving light without pretending~In symbolic play, one thing represents another. A block can stand for a phone even though it is not one.
A child says a taller glass must contain more after water is poured into it. Which concept is relevant?~Conservation~Attachment~Rooting~Bone age~Conservation concerns quantities remaining the same despite a changed appearance. A child may focus on height and overlook the narrower width.
What distinguishes hypothetical reasoning?~Considering what would follow if a proposed condition were true~Relying only on directly visible objects~Repeating an answer without considering possibilities~Measuring only physical size~Hypothetical reasoning explores possibilities, such as predicting outcomes of different experimental conditions. It varies by knowledge and task.
What is self-efficacy?~Belief in one's capacity to perform a task~A guarantee of success in every task~The number of years at school~A measure of infant reflex strength~A student who believes practice can help them solve a problem has task-related confidence. Appropriate feedback and achievable steps can support it.
Why should Piagetian ages be treated as approximate?~Task demands and experience affect performance~All abilities appear on a fixed birthday~Every child fits every stage exactly~Age removes the need to observe reasoning~The stage framework is a useful teaching model with limitations. Children may demonstrate different abilities across tasks and contexts.
How can expertise affect memory?~Knowledge can help organize and retrieve information~Experts have unlimited memory for everything~Experience eliminates working-memory limits~Knowledge never affects recall~A child familiar with a game may remember meaningful game patterns well. Expertise helps organize information within that domain.
''')
quiz(8,'''
What does adaptive functioning concern?~Practical participation in everyday life~Height alone~Only abstract mathematics~Only speech sound accuracy~Adaptive functioning includes daily living and communication used in context. Feeding or dressing with appropriate support are examples.
Which example is prosocial behavior?~Helping a peer pick up dropped materials~Excluding a peer for enjoyment~Taking a toy without regard for others~Ignoring a request for help every time~Prosocial behavior benefits another person. Helping, sharing and comforting are common examples, although ability and context vary.
What is a sensible approach to toilet learning?~Consider readiness, support and individual variation~Require complete night dryness by the second birthday~Treat accidents as deliberate misconduct~Assume one fixed age fits every child~Toileting develops with readiness and practice; night dryness can follow a different course. A rigid birthday rule can mislead.
Why do peer relationships matter in middle childhood?~They provide opportunities for cooperation and belonging~They replace every family relationship~They guarantee emotional wellbeing~They make adult support unnecessary~Friendships offer practice in negotiation, empathy and group participation. Family and adult relationships remain important.
Which response supports turn-taking?~Model it and practise with manageable waits~Expect instant mastery without support~Remove all shared activities~Label every difficulty as bad character~Short, supported turns provide practice. The adult can say “your turn, then mine” and gradually increase waiting.
What should a standardized adaptive assessment use?~The appropriate edition and trained interpretation~A homemade copy treated as an official score~One skill as the total adaptive profile~A score detached from cultural context~Tools such as Vineland have specific editions and procedures. A valid interpretation considers the person's context and multiple domains.
Which statement about adolescent development is most appropriate?~Growing independence can coexist with a need for support~Peers erase the importance of caregivers~Every adolescent has the same priorities~Privacy is proof of a disorder~Adolescents negotiate identity, privacy and relationships. Support can evolve while allowing greater responsibility.
Why is cultural context important in self-care assessment?~Expectations and opportunities to practise differ~It makes all observation impossible~It means functional abilities never matter~It allows one universal routine for every household~Daily tasks are taught and valued differently across settings. Assessment should distinguish limited opportunity from difficulty performing a skill.
What is the best way to interpret difficulty sharing at age three?~Consider emerging regulation, context and support needs~Assume sharing should always be perfect~Diagnose from that single behavior~Avoid peer play permanently~Sharing draws on language, inhibition and perspective-taking, which are still developing. Adults can model and scaffold it.
Which observation best reflects social participation?~Joining a group activity and responding to peers~A single body-weight measurement~The eruption of a permanent molar~The presence of a newborn grasp reflex~Participation concerns involvement in meaningful activities with others. It depends on both the child's skills and the environment's support.
''')
from question_bank_loader import build_bank
build_bank(lessons)

corrections=[
('Reading the early-life claims','Exclusive breastfeeding for about the first six months is a recommended feeding practice, not a developmental risk in itself. Brain connections and infant growth are dynamic. Historical population estimates in these slides should not be read as current statistics.'),
('Prenatal dates and reflexes','Gestational age and age since fertilization use different starting points. Lungs continue maturing late in pregnancy. Plantar grasp differs from the Babinski response. Reflex timing varies by source and context; these notes do not teach home reflex testing.'),
('Milestones are windows','Motor sequences and ages are teaching guides, not diagnostic cutoffs. Crawling pathways vary. Loss of established skills deserves professional discussion. Respectful modern terminology replaces outdated labels in the source wording.'),
('Growth rules need context','Weight-doubling rules and dental ages are approximations. Substantial newborn weight loss needs clinical assessment. Myelination does not finish universally at age five to seven. First permanent molars generally precede premolars. Physical growth alone cannot represent every developmental domain.'),
('Communication terminology','Written expression means writing; understanding written language is comprehension. MLU is an average length in specified linguistic units, not chronological age. Vocabulary counts and intelligibility figures require language and assessment context. Auditory development continues after birth.'),
('Emotional development is contextual','A facial expression cannot reveal an exact emotion with certainty. Attachment builds over repeated interactions and later support can help. Fear and tantrum patterns vary. Kohlberg is a theoretical framework, not a compulsory age schedule. Social referencing is distinct from a full theory of mind.'),
('Use cognitive theories thoughtfully','Piagetian ages organize a theory rather than set fixed diagnostic boundaries. Object-permanence tasks have different demands. Counting skills can emerge before age seven. A fixed attention span or unsupported percentage of people reaching formal operations should not be treated as a universal fact.'),
('Everyday skills vary','Toileting, especially night dryness, is not universally complete at age two. Sharing is still developing in preschool. Peer patterns are not fixed by sex. Adaptive tools must be interpreted using the correct edition, procedures and cultural context.')]
for l,(title,text) in zip(lessons,corrections):l['clarifications']=[dict(title=title,text=text)]
refs=[('CDC · Developmental milestones','https://www.cdc.gov/act-early/milestones/index.html'),('WHO · Child growth standards','https://www.who.int/tools/child-growth-standards'),('WHO · Motor development windows','https://www.who.int/tools/child-growth-standards/standards/motor-development-milestones'),('Stanford Medicine · Newborn reflexes','https://med.stanford.edu/newborns/professional-education/photo-gallery/neuro-reflexes.html'),('NICHD · Healthy pregnancy','https://www.nichd.nih.gov/health/topics/factsheets/pregnancy'),('ASHA · Communication milestones','https://www.asha.org/public/developmental-milestones/communication-milestones-19-to-24-months/'),('ADA · Tooth eruption charts','https://www.mouthhealthy.org/all-topics-a-z/eruption-charts'),('WHO · Breastfeeding','https://www.who.int/health-topics/breastfeeding'),('OpenStax · Lifespan theories','https://openstax.org/books/lifespan-development/pages/1-3-major-theories-and-theorists'),('OpenStax · Developmental contexts','https://openstax.org/books/lifespan-development/pages/1-4-contexts-and-settings-of-development')]
for l in lessons:
 for s in l['slides']:s['text']=s['text'].replace('\r','\n').replace('\v','\n')
 for q in l['questions']:assert len(set(q['options']))==4 and 0<=q['answer']<4
assert len(lessons)==8 and sum(len(l['questions']) for l in lessons)==600
out=dict(title='Growing Minds',lessons=lessons,references=[dict(title=a,url=b) for a,b in refs],assignments=[dict(lecture=3,title='Technoference and child development',text='Discuss technology interrupting adult–child interaction. The supplied assignment asks for 1,500–2,000 words, references and a PDF soft submission.'),dict(lecture=4,title='Physical growth as a proxy for development',text='Critically discuss physical growth as a proxy for development in low- and middle-income countries. The supplied assignment asks for 1,500–2,000 words, references and soft submission.')])
Path('data.json').write_text(json.dumps(out,ensure_ascii=False))
print(json.dumps(dict(lectures=len(lessons),topics=sum(len(l['topics']) for l in lessons),slides=sum(len(l['slides']) for l in lessons),questions=sum(len(l['questions']) for l in lessons))))
